import { load } from "@2gis/mapgl";
import { useEffect } from "react";
import React from "react";
import { FeatureCollection, Geometry, GeoJsonProperties } from "geojson";
import geoData from "./data/data.json"; 

export const MAP_CENTER = [50.100202, 53.195878]; 
export const Map = () => {
  useEffect(() => {
    let map;
    let isDestroyed = false;

    load().then((mapglAPI) => {
      if (isDestroyed) return;

     
      map = new mapglAPI.Map("map-container", {
        center: MAP_CENTER,
        zoom: 13,
        key: "15810811-e0e6-44b2-9b46-cf1e58549aac",
        style: "4ef1c3fd-de28-4802-a6d5-7935bc8aed53",
      });

      const source = new mapglAPI.GeoJsonSource(map, {
        data: geoData, 
        attributes: {
          visible: true,
        },
      });

      const layer = {
        id: "dtp-data-layer",
        filter: [
          "all",
          ["match", ["sourceAttr", "visible"], [true], true, false],
        ],
        type: "point",
        style: {
          iconImage: "caution",
          iconWidth: 15,
          textField: ["get", "category"],
          textFont: ["Noto_Sans"],
          textColor: "#000000",
          textHaloColor: "#fff",
          textHaloWidth: 1,
          iconPriority: 100,
          textPriority: 100,
        },
      };

      map.on("styleload", () => {
        map.addLayer(layer);
      });
    });

    return () => {
      isDestroyed = true;
      if (map) {
        map.destroy();
      }
    };
  }, []);

  return (
    <div style={{ width: "100%", height: "100%" }}>
      <MapWrapper />
    </div>
  );
};

const MapWrapper = React.memo(
  () => {
    return (
      <div id="map-container" style={{ width: "100%", height: "100%" }}></div>
    );
  },
  () => true,
);
